mapper.select:
SELECT COUNT(*) FROM ${table}
WHERE tenant_id = #{tenantId} AND project_id = #{projectId} AND deleted = 1
AND (doc_code LIKE CONCAT('%', #{keyword}, '%') OR doc_name LIKE CONCAT('%', #{keyword}, '%'))

SELECT , deleted_by, deleted_at FROM ${table}
WHERE tenant_id = #{tenantId} AND project_id = #{projectId} AND deleted = 1
AND (doc_code LIKE CONCAT('%', #{keyword}, '%') OR doc_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY (doc_code IS NULL OR doc_code = ''), doc_code ASC, deleted_at DESC, id ASC LIMIT #{limit}

SELECT COUNT(*) FROM dm_rule
WHERE tenant_id = #{tenantId} AND deleted = 0 AND id <> #{id}
  AND (JSON_UNQUOTE(JSON_EXTRACT(structured_data, '$.tableStructureId')) = #{idText}
    OR JSON_UNQUOTE(JSON_EXTRACT(structured_data, '$.intermediateTableId')) = #{idText}
    OR JSON_UNQUOTE(JSON_EXTRACT(structured_data, '$.targetTableId')) = #{idText}
    OR JSON_UNQUOTE(JSON_EXTRACT(structured_data, '$.sourceTableId')) = #{idText})
